const processImages = true;
const event = $('Webhook').first().json.body;
let reason = '';
if (!event || event.schema_version !== 1 || typeof event.event_id !== 'string' ||
    !event.event_id || !['test', 'notification', 'sms'].includes(event.message_type) ||
    typeof event.text !== 'string') reason = 'Invalid Message487 event';
const images = event?.images ?? [];
if (!Array.isArray(images)) reason = 'images must be an array';
else if (processImages && images.some(image => !image || !['image/jpeg', 'image/png'].includes(image.mime_type) ||
    !Number.isInteger(image.width) || image.width <= 0 || !Number.isInteger(image.height) || image.height <= 0 ||
    typeof image.data_base64 !== 'string' || !image.data_base64.length ||
    image.data_base64.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(image.data_base64))) {
  reason = 'Invalid JPEG/PNG image';
}
return [{ json: { valid: !reason, reason, event_id: event?.event_id ?? null } }];

const timeZone = 'UTC';
const locale = 'en-GB';
const messageTypes = { sms: 'SMS', notification: 'Notification', test: 'Test' };
const event = $('Webhook').first().json.body;

if (!event || event.schema_version !== 1 ||
    typeof event.event_id !== 'string' || !event.event_id ||
    !Object.hasOwn(messageTypes, event.message_type) ||
    typeof event.text !== 'string') {
  throw new Error('Invalid Message487 event');
}

const escapeHtml = value => value.replace(/[&<>]/g, character => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;',
})[character]);
const firstText = (...values) => values.find(value => typeof value === 'string' && value) || '—';
const date = new Date(event.occurred_at);
const timestamp = typeof event.occurred_at === 'string' && !Number.isNaN(date.getTime())
  ? new Intl.DateTimeFormat(locale, {
    timeZone, day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
  }).format(date).replace(/,/g, '')
  : '—';
const source = firstText(event.sender, event.source_name, event.source);
const device = firstText(event.device_code, event.device_id);
const segments = [
  { text: 'Message487: ', bold: false },
  { text: source, bold: true },
  { text: '\n', bold: false },
  { text: `${messageTypes[event.message_type]}\n${device}\n${timestamp}`, bold: true },
  { text: '\n', bold: false },
  { text: typeof event.title === 'string' && event.title ? `${event.title}\n` : '', bold: false },
  { text: event.text, bold: false },
];

// Split unescaped text and close formatting in each part to keep HTML valid.
const chunks = [];
let html = '';
let length = 0;
for (const segment of segments) {
  let run = '';
  const flush = () => {
    if (run) {
      const escaped = escapeHtml(run);
      html += segment.bold ? `<b>${escaped}</b>` : escaped;
      run = '';
    }
  };
  for (const character of segment.text) {
    if (length + character.length > 3500) {
      flush();
      chunks.push(html);
      html = '';
      length = 0;
    }
    run += character;
    length += character.length;
  }
  flush();
}
if (html) chunks.push(html);

return chunks.map((part, index) => ({
  json: {
    telegram_text: chunks.length > 1 ? `[${index + 1}/${chunks.length}]\n${part}` : part,
  },
}));

// Attach all media to the first text part as one Rich Message.
const event = $('Webhook').first().json.body;
const images = event.images ?? [];
if (!Array.isArray(images)) throw new Error('Invalid images collection');
const result = $input.all();
const gallery = [];
const icons = [];
const binaryImage = (image, index) => {
  if (!image || !['image/jpeg', 'image/png'].includes(image.mime_type) ||
      typeof image.data_base64 !== 'string' || !image.data_base64.length ||
      image.data_base64.length % 4 !== 0 ||
      !/^[A-Za-z0-9+/]*={0,2}$/.test(image.data_base64)) {
    throw new Error(`Invalid image ${index + 1}`);
  }
  const extension = image.mime_type === 'image/png' ? 'png' : 'jpg';
  const kind = ['attachment', 'avatar', 'app_icon'].includes(image.kind) ? image.kind : 'attachment';
  return { data: image.data_base64, mimeType: image.mime_type, fileName: `${kind}-${index + 1}.${extension}` };
};
const blocks = [];
const binary = {};
for (const [index, image] of images.entries()) {
  binary[`image${index}`] = binaryImage(image, index);
  const photo = { type: 'photo', photo: { type: 'photo', media: `attach://file${index}` } };
  if (['avatar', 'app_icon'].includes(image.kind)) {
    photo.caption = { text: image.kind === 'avatar' ? 'Avatar' : 'Application icon' };
    icons.push(photo);
  } else if (image.presentation === 'gallery') {
    gallery.push(photo);
  } else if (image.presentation === 'big_picture') {
    blocks.push(photo);
  } else {
    blocks.push({ type: 'document', document: { type: 'document', media: `attach://file${index}` } });
  }
}
for (const photos of [gallery, icons]) {
  if (photos.length) blocks.push(photos.length > 1 ? { type: 'collage', blocks: photos } : photos[0]);
}
// Preserve the formatter's bold/italic text without interpreting escaped user HTML.
if (images.length) {
  const first = result[0];
  if (!first || typeof first.json.telegram_text !== 'string') throw new Error('Missing notification text');
  let bold = false;
  let italic = false;
  const text = [];
  for (const token of first.json.telegram_text.split(/(<\/?[bi]>)/)) {
    if (token === '<b>' || token === '</b>') { bold = token === '<b>'; continue; }
    if (token === '<i>' || token === '</i>') { italic = token === '<i>'; continue; }
    if (!token) continue;
    let value = token.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
    if (italic) value = { type: 'italic', text: value };
    if (bold) value = { type: 'bold', text: value };
    text.push(value);
  }
  blocks.unshift({ type: 'paragraph', text });
  first.json.telegram_operation = 'sendRichMessage';
  first.json.rich_message = { blocks };
  first.binary = binary;
}
return result;
